/* Modernes Menü + Sprachauswahl (Nutzerwunsch 17.10.2026) */
(() => {
  const sheet = document.getElementById("menuSheet"), row = sheet && sheet.querySelector(".row");
  if (!row) return;
  const st = document.createElement("style");
  st.textContent = `
#menuSheet{padding:10px 14px 14px !important;border-radius:24px !important;max-height:min(74vh,660px);overflow-y:auto;overscroll-behavior:contain;background:linear-gradient(180deg,rgba(24,28,62,.86),rgba(9,11,26,.92)) !important;border:1px solid rgba(190,205,255,.16) !important;box-shadow:0 28px 80px -24px rgba(0,0,0,.95),inset 0 1px 0 rgba(255,255,255,.06) !important;backdrop-filter:blur(22px) saturate(1.2);-webkit-backdrop-filter:blur(22px) saturate(1.2);scrollbar-width:thin}
#menuSheet::after{display:none !important}
#menuSheet::before{content:"";display:block;width:40px;height:4px;border-radius:4px;background:rgba(210,222,255,.28);margin:0 auto 12px}
#menuSheet:not([hidden]){animation:skyUp .24s cubic-bezier(.2,.8,.2,1)}
@keyframes skyUp{from{opacity:0;transform:translate(-50%,14px)}to{opacity:1;transform:translate(-50%,0)}}
#menuSheet .row{display:grid;grid-template-columns:1fr 1fr;gap:8px;justify-content:stretch}
#menuSheet .row>.note,#menuSheet .row>a.chip,#menuSheet .row>#langBox{grid-column:1/-1}
#menuSheet button.chip{display:flex;align-items:center;justify-content:space-between;gap:10px;text-align:start;min-height:48px;padding:11px 14px !important;border-radius:14px !important;font-size:14px;letter-spacing:0;color:var(--ink);background:rgba(255,255,255,.05);border:1px solid rgba(190,205,255,.12);box-shadow:none !important;transition:background .18s,border-color .18s}
#menuSheet button.chip:active{transform:scale(.98)}
#menuSheet button.chip::after{content:"";flex:none;width:36px;height:22px;border-radius:22px;background-color:rgba(255,255,255,.16);background-image:radial-gradient(circle,#fff 0 8px,transparent 8.5px);background-size:22px 22px;background-repeat:no-repeat;background-position:0 0;transition:background-position .18s,background-color .18s}
#menuSheet button.chip[aria-pressed="true"]{background:rgba(255,90,77,.12);border-color:rgba(255,90,77,.45)}
#menuSheet button.chip[aria-pressed="true"]::after{background-color:rgba(255,90,77,.92);background-position:14px 0}
[dir="rtl"] #menuSheet button.chip::after{background-position:100% 0}
[dir="rtl"] #menuSheet button.chip[aria-pressed="true"]::after{background-position:calc(100% - 14px) 0}
#menuSheet .row>.note{font-size:11px;line-height:1.5;opacity:.7;margin:2px 4px 0 !important;text-align:center}
#menuSheet a.chip{display:block;text-align:center;border-radius:14px !important;padding:14px !important;font-size:14px;letter-spacing:0}
#menuSheet a.chip#sizeLink{background:linear-gradient(135deg,rgba(255,90,77,.22),rgba(255,90,77,.06));border-color:rgba(255,90,77,.55) !important}
#menuSheet a.chip#backLink{background:rgba(255,255,255,.04)}
#langBox{padding:2px 0 6px}
#langBox .lbl{font:600 11px/1 var(--font-sans);letter-spacing:.14em;text-transform:uppercase;color:var(--muted);margin:0 2px 8px}
#langStrip{display:grid;grid-template-columns:repeat(auto-fill,minmax(94px,1fr));gap:6px}
#langStrip button{display:flex;align-items:center;gap:6px;padding:8px 9px;border-radius:12px;font:500 13px/1.1 var(--font-sans);color:var(--muted);background:rgba(255,255,255,.04);border:1px solid rgba(190,205,255,.1);cursor:pointer;text-align:start;transition:background .15s,border-color .15s,color .15s}
#langStrip button:hover{color:var(--ink);background:rgba(255,255,255,.08)}
#langStrip button[aria-current="true"]{color:var(--ink);border-color:rgba(255,90,77,.6);background:rgba(255,90,77,.14)}
#langStrip .fl{font-size:17px;line-height:1;flex:none}
@media (max-width:380px){#menuSheet .row{grid-template-columns:1fr}}
`;
  document.head.appendChild(st);

  const LS = [["de", "🇩🇪", "Deutsch"], ["en", "🇬🇧", "English"], ["es", "🇪🇸", "Español"], ["fr", "🇫🇷", "Français"], ["pt", "🇵🇹", "Português"], ["tr", "🇹🇷", "Türkçe"], ["ru", "🇷🇺", "Русский"], ["el", "🇬🇷", "Ελληνικά"], ["ar", "🇸🇦", "العربية"], ["hi", "🇮🇳", "हिन्दी"], ["zh", "🇨🇳", "中文"], ["ja", "🇯🇵", "日本語"], ["ko", "🇰🇷", "한국어"], ["id", "🇮🇩", "Indonesia"], ["fa", "🇮🇷", "فارسی"]];
  const box = document.createElement("div");
  box.id = "langBox";
  const cur = LS.find((x) => x[0] === LANG) || LS[0];
  const lbl = document.createElement("button");
  lbl.type = "button";
  lbl.className = "lbl";
  lbl.setAttribute("aria-expanded", "false");
  lbl.style.cssText = "display:flex;align-items:center;justify-content:space-between;gap:8px;width:100%;background:none;border:0;padding:0;font:inherit;letter-spacing:inherit;text-transform:inherit;color:inherit;cursor:pointer;text-align:start";
  const lt = document.createElement("span");
  lt.textContent = "🌐 " + cur[1] + " " + cur[2] + " · Language";
  const ch = document.createElement("span");
  ch.textContent = "▾";
  ch.style.transition = "transform .2s";
  lbl.append(lt, ch);
  const strip = document.createElement("div");
  strip.id = "langStrip";
  strip.style.display = "none";
  lbl.addEventListener("click", () => {
    const open = strip.style.display === "none";
    strip.style.display = open ? "" : "none";
    lbl.setAttribute("aria-expanded", String(open));
    ch.style.transform = open ? "rotate(180deg)" : "";
  });
  const go = (l) => {
    try { localStorage.setItem("centaurian-lang", l); } catch (e) {}
    const q = new URLSearchParams(location.search);
    q.delete("lang");
    const extra = [];
    if (q.get("c")) extra.push("c=" + encodeURIComponent(q.get("c")));
    if (q.get("p")) extra.push("p=" + encodeURIComponent(q.get("p")));
    const url = (l === "de" ? "" : "/" + l) + "/sternenhimmel" + (extra.length ? "?" + extra.join("&") : "");
    try { (window.top || window).location.href = url; } catch (e) { location.href = "/sternenhimmel.html?lang=" + l; }
  };
  for (const [code, flag, name] of LS) {
    const b = document.createElement("button");
    b.type = "button";
    b.lang = code;
    if (code === LANG) b.setAttribute("aria-current", "true");
    const f = document.createElement("span");
    f.className = "fl";
    f.textContent = flag;
    const n = document.createElement("span");
    n.textContent = name;
    b.append(f, n);
    b.addEventListener("click", () => { if (code !== LANG) go(code); });
    strip.appendChild(b);
  }
  box.append(lbl, strip);
  row.insertBefore(box, row.firstChild);
})();

